// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint96 depositAmount) public {
        address depositor = address(0x1234);
        vm.assume(depositAmount > 0);
        uint256 initialContractBalance = address(c).balance;
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();
        assertTrue(address(c).balance == initialContractBalance + depositAmount);
    }
}
